  function [x0, Ax, d, normd] = lsplane(X)% ---------------------------------------------------------------------% LSPLANE.M   Least-squares plane (orthogonal distance%             regression).%% Version 1.0    % Obtained from http://www.eurometros.org/% Last amended   I M Smith 27 May 2002. % Created        I M Smith 08 Mar 2002% ---------------------------------------------------------------------% Input    % X        Array [x y z] where x = vector of x-coordinates, %          y = vector of y-coordinates and z = vector of %          z-coordinates. %          Dimension: m x 3. % % Output   % x0       Centroid of the data = point on the best-fit plane.%          Dimension: 3 x 1. % % Ax       Direction cosines of the new coordinate system%          Ax = [x_axis y_axis normal_axis]%          Dimension: 3 x 3.% % <Optional... % d        Residuals. %          Dimension: m x 1. % % normd    Norm of residual errors. %          Dimension: 1 x 1. % ...>%% [x0, a <, d, normd >] = lsplane(X)% ---------------------------------------------------------------------% check number of data points   m = size(X, 1);  if m < 3    error('At least 3 data points required: ' )  end%% remove all NaNsXf = X(~isnan(X(:,1)),:) ;% calculate centroid  x0 = mean(Xf)';%% form matrix A of centered points  A = [(Xf(:, 1) - x0(1)) (Xf(:, 2) - x0(2)) (Xf(:, 3) - x0(3))];%% calculate the SVD of A  [U, S, V] = svd(A, 0);%% find the smallest singular value in S and extract from V the% corresponding right singular vector  [s, i] = sort(diag(S),'descend');  ax1 = V(:,i(1)) ;  ax2 = V(:,i(2)) ;  ax3 = V(:,i(3)) ;  Ax = [ax1 ax2 ax3] ;  [~,Ax] = isRightHandedCS(Ax') ;  Ax = Ax' ;%% calculate residual distances, if required    if nargout > 2    d = U(:, i)*s;    normd = norm(d);  end% ---------------------------------------------------------------------% End of LSPLANE.M.